'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const path = require('node:path');

const CLI = path.join(__dirname, 'jsonfmt.js');

function runCli(args, stdin) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [CLI, ...args]);
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => { stdout += d; });
    child.stderr.on('data', (d) => { stderr += d; });
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
    child.stdin.end(stdin);
  });
}

test('pretty-prints with sorted keys recursively', async () => {
  const input = JSON.stringify({
    zebra: 1,
    apple: { delta: true, charlie: [3, { y: 2, x: 1 }] },
    banana: null,
  });
  const { code, stdout, stderr } = await runCli([], input);

  assert.strictEqual(code, 0, `expected exit 0, stderr: ${stderr}`);
  assert.strictEqual(stdout, [
    '{',
    '  "apple": {',
    '    "charlie": [',
    '      3,',
    '      {',
    '        "x": 1,',
    '        "y": 2',
    '      }',
    '    ],',
    '    "delta": true',
    '  },',
    '  "banana": null,',
    '  "zebra": 1',
    '}',
    '',
  ].join('\n'));
});

test('--compact minifies output but still sorts keys', async () => {
  const input = '{"b":2,"a":{"d":4,"c":3}}';
  const { code, stdout, stderr } = await runCli(['--compact'], input);

  assert.strictEqual(code, 0, `expected exit 0, stderr: ${stderr}`);
  assert.strictEqual(stdout, '{"a":{"c":3,"d":4},"b":2}');
});

test('truncated JSON exits 1 with error on stderr and nothing on stdout', async () => {
  const { code, stdout, stderr } = await runCli([], '{"a": [1, 2');

  assert.strictEqual(code, 1);
  assert.strictEqual(stdout, '');
  assert.ok(stderr.trim().length > 0, 'stderr should contain the parse error message');
});

